import pysam, collections
ref = pysam.FastaFile('/tmp/som/hg19mini.fasta')
bams = {s: pysam.AlignmentFile(f'/tmp/som/{s}.bam') for s in ['tumor','normal']}

def counts(bam):
    """position -> Counter of observed bases, using mpileup-equivalent settings"""
    d = {}
    for col in bam.pileup(min_base_quality=20, min_mapping_quality=20,
                          stepper='samtools', max_depth=10000, truncate=True):
        c = collections.Counter()
        for pr in col.pileups:
            if pr.is_del or pr.is_refskip: continue
            b = pr.alignment.query_sequence[pr.query_position].upper()
            if b in 'ACGT': c[b]+=1
        d[(col.reference_name, col.reference_pos)] = c   # 0-based
    return d

cnt = {s: counts(b) for s,b in bams.items()}
print({s: len(v) for s,v in cnt.items()})

# candidate: any site where non-ref base fraction >= 10% and >=4 supporting reads in EITHER sample
cands = []
allpos = set(cnt['tumor']) | set(cnt['normal'])
for key in sorted(allpos):
    chrom, pos0 = key
    rb = ref.fetch(chrom, pos0, pos0+1).upper()
    row = {'chrom':chrom,'pos':pos0+1,'ref':rb}
    keep = False
    for s in ['tumor','normal']:
        c = cnt[s].get(key, collections.Counter())
        dp = sum(c.values())
        alt_b, alt_n = ('.',0)
        nonref = {b:n for b,n in c.items() if b!=rb}
        if nonref:
            alt_b, alt_n = max(nonref.items(), key=lambda x:x[1])
        vaf = alt_n/dp if dp else 0
        row[s] = dict(dp=dp, alt=alt_b, alt_n=alt_n, vaf=vaf)
        if alt_n >= 4 and vaf >= 0.10:
            keep = True
    if keep: cands.append(row)
print("candidate variant sites:", len(cands))
for r in cands:
    print(f"{r['chrom']}:{r['pos']} ref={r['ref']}  T: {r['tumor']['alt']} {r['tumor']['alt_n']}/{r['tumor']['dp']} VAF={r['tumor']['vaf']:.3f}   N: {r['normal']['alt']} {r['normal']['alt_n']}/{r['normal']['dp']} VAF={r['normal']['vaf']:.3f}")

